css:
#tongsci2-2-2-2-1-lab .frame { gap: 20px; }
#tongsci2-2-2-2-1-lab .head { display: flex; align-items: flex-end; justify-content: space-between; gap: 32px; }
#tongsci2-2-2-2-1-lab .head .titles { display: flex; flex-direction: column; gap: 6px; }
#tongsci2-2-2-2-1-lab .head .pen { font-size: 44px; transform: rotate(-1.5deg); padding-bottom: 6px; white-space: nowrap; }
#tongsci2-2-2-2-1-lab .body { flex: 1 1 auto; min-height: 0; display: grid; grid-template-columns: 1060px 1fr; gap: 28px; }
#tongsci2-2-2-2-1-lab .body { grid-template-rows: minmax(0, 1fr); }

js:
/* tongsci2.2-2-2.1.lab */
(function () {
  'use strict';
  const { part } = window.Deck;

  part('tongsci2-2-2-2-1-lab', (root) => window.InductionLab.mount(root, { stepped: true }));   // 보이는 줄 수가 바뀔 때만 바늘이 움직인다
})();
(function () {
  'use strict';
  const { part } = window.Deck;

  part('tongsci2-2-2-2-1-lab', (root) => window.Gx.track(root, ['magnet', 'coil', 'both'].map((m) => (r) => r.querySelector(`.checks li[data-mode="${m}"]`).classList.contains('done'))));
})();
